#!/usr/bin/env node
import fs from 'fs';
import path from 'path';
import sharp from 'sharp';
import { uploadSprite } from './sprite-uploader.js';
import { fileURLToPath } from 'url';
import crypto from 'crypto';

// 计算文件的MD5哈希值
async function calculateMD5(filePath) {
  return new Promise((resolve, reject) => {
    const hash = crypto.createHash('md5');
    const stream = fs.createReadStream(filePath);
    
    stream.on('error', err => reject(err));
    stream.on('data', chunk => hash.update(chunk));
    stream.on('end', () => resolve(hash.digest('hex')));
  });
}

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const SPRITE_SIZE = process.argv.includes('-r') ? parseInt(process.argv[process.argv.indexOf('-r') + 1]) : 1024;
const IMAGE_PADDING = 4;

const inputFolder = process.argv[2];
const outputFolder = process.argv[3];
const forceClearCache = process.argv.includes('-c');

// 递归获取文件夹及其子文件夹中的所有图片
function getAllImagePaths(dir) {
  const images = [];
  const files = fs.readdirSync(dir);

  for (const file of files) {
    const filePath = path.join(dir, file);
    const stats = fs.statSync(filePath);

    if (stats.isDirectory()) {
      images.push(...getAllImagePaths(filePath));
    } else {
      const ext = path.extname(file).toLowerCase();
      if (ext === '.png' || ext === '.jpg' || ext === '.jpeg') {
        images.push(filePath);
      }
    }
  }

  return images;
}

// 按文件夹分组图片
function groupImagesByFolder(images) {
  const groups = new Map();
  
  for (const imagePath of images) {
    const relativePath = path.relative(inputFolder, imagePath);
    // 使用文件所在的完整文件夹路径作为分组依据
    const folderPath = path.dirname(relativePath);
    
    if (!groups.has(folderPath)) {
      groups.set(folderPath, []);
    }
    groups.get(folderPath).push(imagePath);
  }
  
  return groups;
}

const imageFiles = getAllImagePaths(inputFolder);
const imageGroups = groupImagesByFolder(imageFiles);

// 获取图片的元数据
async function getImageMetadata(imagePath) {
  try {
    const metadata = await sharp(imagePath).metadata();
    return {
      path: imagePath,
      width: metadata.width,
      height: metadata.height
    };
  } catch (error) {
    console.error(`无法获取图片元数据: ${imagePath} 错误: ${error.message}`);
    return null;
  }
}

// 按面积从大到小排序图片
async function getSortedImagePaths(imageFiles) {
  const imageMetadatas = await Promise.all(imageFiles.map(getImageMetadata));
  const filteredMetadatas = imageMetadatas.filter(meta => meta !== null);

  // 按面积降序排序
  filteredMetadatas.sort((a, b) => {
    const areaA = a.width * a.height;
    const areaB = b.width * b.height;
    return areaB - areaA;
  });

  return filteredMetadatas.map(meta => meta.path);
}

// 对图片进行等比例缩放
async function resizeImage(imagePath) {
  try {
    const metadata = await sharp(imagePath).metadata();
    const { width: originalWidth, height: originalHeight } = metadata;

    const maxDimension = Math.max(originalWidth, originalHeight);
    if (maxDimension <= SPRITE_SIZE) {
      return imagePath;
    }

    const scale = SPRITE_SIZE / maxDimension;
    // 四舍五入到整数
    const newWidth = Math.round(originalWidth * scale);
    const newHeight = Math.round(originalHeight * scale);

    const outputPath = path.join(path.dirname(imagePath), `resized_${originalWidth}_${originalHeight}_${path.basename(imagePath)}`);
    await sharp(imagePath)
      .resize(newWidth, newHeight, { withoutEnlargement: true })
      .toFile(outputPath);

    console.log(`图片 ${imagePath} 缩放至 [${newWidth}x${newHeight}]，保存为 ${outputPath}`);
    return outputPath;
  } catch (error) {
    console.error(`缩放图片失败: ${imagePath} 错误: ${error.message}`);
    return null;
  }
}

// 全局配置对象
let globalConfig = {};
let cacheDir;

const processImages = async () => {
  try {
    if (!fs.existsSync(outputFolder)) {
      fs.mkdirSync(outputFolder, { recursive: true });
      console.log(`创建输出文件夹: ${outputFolder}`);
    }

    // 创建cache目录
    cacheDir = path.join(path.dirname(__dirname), 'cache', path.basename(inputFolder));
    if (!fs.existsSync(cacheDir)) {
      fs.mkdirSync(cacheDir, { recursive: true });
    }

    // 如果指定了-c参数，则清理所有缓存文件
    if (forceClearCache) {
      if (fs.existsSync(cacheDir)) {
        const cacheFiles = fs.readdirSync(cacheDir);
        for (const file of cacheFiles) {
          fs.unlinkSync(path.join(cacheDir, file));
          console.log(`清理缓存文件: ${file}`);
        }
      }
    } else {
      // 仅清理旧的精灵图文件，保留JSON文件
      const cacheFiles = fs.readdirSync(cacheDir);
      for (const file of cacheFiles) {
        if (file.endsWith('.png')) {
          fs.unlinkSync(path.join(cacheDir, file));
          console.log(`清理旧的精灵图: ${file}`);
        }
      }
    }

    // 为每个文件夹组分别处理图片
    let groupIndex = 0;
    for (const [folderPath, groupImages] of imageGroups) {
      console.log(`处理文件夹 ${folderPath} 中的图片...`);
      const sortedImageFiles = await getSortedImagePaths(groupImages);

    // 缩放图片（如果需要）
    const resizedImageFiles = [];
    for (const imagePath of sortedImageFiles) {
      const resizedPath = await resizeImage(imagePath);
      if (resizedPath) {
        resizedImageFiles.push(resizedPath);
      } else {
        console.error(`无法缩放图片: ${imagePath}`);
      }
    }

    // 精灵图容器
    const bins = [];
    
    // 初始化第一个精灵图容器
    bins.push({
      images: [],
      width: SPRITE_SIZE,
      height: SPRITE_SIZE,
      usedWidth: 0,
      usedHeight: 0,
      availableSpaces: [
        { x: 0, y: 0, width: SPRITE_SIZE, height: SPRITE_SIZE }
      ]
    });

    // 遍历缩放后的图片
    for (const imagePath of resizedImageFiles) {
      const metadata = await sharp(imagePath).metadata();

      if (metadata.width > SPRITE_SIZE || metadata.height > SPRITE_SIZE) {
        console.error(`Image ${imagePath} 尺寸仍然过大，已跳过`);
        continue;
      }

      let placed = false;

      // 遍历所有精灵图容器，查找是否有足够的空间
      for (let i = 0; i < bins.length; i++) {
        const bin = bins[i];
        const availableSpaces = bin.availableSpaces;

        for (let j = 0; j < availableSpaces.length; j++) {
          const space = availableSpaces[j];
          
          if (metadata.width + IMAGE_PADDING <= space.width && 
              metadata.height + IMAGE_PADDING <= space.height) {
            // 放置图片
            bin.images.push({
              imagePath,
              x: space.x,
              y: space.y,
              width: metadata.width,
              height: metadata.height
            });
            
            // 更新可用空间
            availableSpaces.splice(j, 1);
            availableSpaces.push({
              x: space.x + metadata.width + IMAGE_PADDING,
              y: space.y,
              width: space.width - metadata.width - IMAGE_PADDING,
              height: space.height
            });

            if (metadata.height < space.height) {
              availableSpaces.push({
                x: space.x,
                y: space.y + metadata.height + IMAGE_PADDING,
                width: metadata.width + IMAGE_PADDING,
                height: space.height - metadata.height - IMAGE_PADDING
              });
            }

            placed = true;
            break;
          }
        }

        if (placed) break;
      }

      // 如果无法放置，创建新的精灵图容器
      if (!placed) {
        const newBin = {
          images: [ {
            imagePath,
            x: 0,
            y: 0,
            width: metadata.width,
            height: metadata.height
          } ],
          width: SPRITE_SIZE,
          height: SPRITE_SIZE,
          availableSpaces: [ {
            x: metadata.width + IMAGE_PADDING,
            y: 0,
            width: SPRITE_SIZE - metadata.width - IMAGE_PADDING,
            height: SPRITE_SIZE
          } ]
        };

        if (metadata.height < SPRITE_SIZE) {
          newBin.availableSpaces.push({
            x: 0,
            y: metadata.height + IMAGE_PADDING,
            width: metadata.width + IMAGE_PADDING,
            height: SPRITE_SIZE - metadata.height - IMAGE_PADDING
          });
        }

        bins.push(newBin);
      }
    }

    const spriteAssets = {};
    // 生成精灵图
    async function generateSprite(bins, folderPath, outputFolder) {
      const folderName = folderPath.replace(/[\\/:*?"<>|]/g, '_');
      
      // 为每个bin生成精灵图
      for (let i = 0; i < bins.length; i++) {
        const bin = bins[i];
        const compositeOperations = [];
        
        // 准备合成操作
        for (const img of bin.images) {
          compositeOperations.push({
            input: img.imagePath,
            top: img.y,
            left: img.x
          });
        }
        
        // 创建精灵图
        try {
          // 在cache目录中生成精灵图
          const cachePath = path.join(cacheDir, `${folderName}_sprite_${i + 1}.png`);
          await sharp({
            create: {
              width: SPRITE_SIZE,
              height: SPRITE_SIZE,
              channels: 4,
              background: { r: 0, g: 0, b: 0, alpha: 0 }
            }
          })
          .composite(compositeOperations)
          .png()
          .toFile(cachePath);
          
          console.log(`生成精灵图: ${cachePath}`);

          // 检查是否存在对应的JSON文件
          const infoPath = path.join(cacheDir, `${folderName}_sprite_${i + 1}_info.json`);
          if (fs.existsSync(infoPath)) {
            try {
              const oldInfo = JSON.parse(fs.readFileSync(infoPath, 'utf8'));
              let allImagesUnchanged = true;
              const imageChecks = [];
              
              // 遍历当前精灵图中的所有图片
              for (const img of bin.images) {
                const imageName = path.basename(img.imagePath);
                const md5 = await calculateMD5(img.imagePath);
                
                // 检查图片是否在旧信息中存在，且MD5值相同
                const oldImageInfo = oldInfo.images[imageName];
                if (!oldImageInfo || oldImageInfo.md5 !== md5 || 
                  oldImageInfo.x !== img.x || oldImageInfo.y !== img.y || 
                  oldImageInfo.width !== img.width || oldImageInfo.height !== img.height) {
                    allImagesUnchanged = false;
                    break;
                  }
                imageChecks.push({ imageName, md5 });
              }
              
              // 如果所有图片都没有变化，直接使用旧的assetId
              if (allImagesUnchanged) {
                // && Object.keys(oldInfo.images).length === bin.images.length
                // 遍历oldInfo.images，检查是否所有图片都在新的bin.images中
                let allImagesInNewBin = true;
                for (const imageName in oldInfo.images) {
                  if (!bin.images.some(img => path.basename(img.imagePath) === imageName)) {
                    allImagesInNewBin = false;
                    break;
                  }
                }

                if (allImagesInNewBin) {
                  spriteAssets[i] = oldInfo.assetId;
                  console.log(`精灵图 ${folderName}_sprite_${i + 1} 未发生变化，使用缓存的assetId: ${oldInfo.assetId}`);
                  continue;
                }
              }
            } catch (error) {
              console.error(`读取JSON文件失败: ${error.message}`);
            }
          }

        } catch (error) {
          console.error(`生成精灵图失败: ${error.message}`);
        }
      }
    }

    // 收集配置信息
    async function collectConfig(bins, folderPath) {

      const config = {};
      const folderName = folderPath.replace(/[\\/:*?"<>|]/g, '_');
      const spriteInfo = {};
    
      // 先上传所有精灵图并保存assetId
      for (let i = 0; i < bins.length; i++) {
        const spritePath = path.join(cacheDir, `${folderName}_sprite_${i + 1}.png`);
        // 跳过已上传的精灵图
        var assetId = spriteAssets[i]
        if (spriteAssets[i] === undefined) {
          // 上传精灵图
          assetId = await uploadSprite(spritePath, `${folderName}_sprite_${i + 1}`);
          spriteAssets[i] = assetId;
        }
    
        // 收集该精灵图中所有图片的信息
        const imageInfos = {};
        for (const img of bins[i].images) {
          const imageName = path.basename(img.imagePath);
          const md5 = await calculateMD5(img.imagePath);
          imageInfos[imageName] = {
            md5,
            x: img.x,
            y: img.y,
            width: img.width,
            height: img.height
          };
        }
    
        // 保存精灵图信息
        spriteInfo[`${folderName}_sprite_${i + 1}`] = {
          assetId,
          images: imageInfos
        };
    
        // 生成精灵图信息文件
        const infoPath = path.join(cacheDir, `${folderName}_sprite_${i + 1}_info.json`);
        fs.writeFileSync(infoPath, JSON.stringify(spriteInfo[`${folderName}_sprite_${i + 1}`], null, 2), 'utf8');
        console.log(`生成精灵图信息文件: ${infoPath}`);
      }
    
      // 使用已上传的精灵图assetId生成配置
      for (let i = 0; i < bins.length; i++) {
        const bin = bins[i];
        for (const img of bin.images) {
          const relativePath = path.relative(inputFolder, img.imagePath);
          // 只获取第一级子文件夹名称
          const firstLevelFolder = relativePath.split(path.sep)[0];
          const imageName = path.basename(relativePath, path.extname(relativePath));
          // if (imageName.startsWith('resized')) continue;
    
          if (!config[firstLevelFolder]) {
            config[firstLevelFolder] = {};
          }
          config[firstLevelFolder][imageName] = {
            Image: `"rbxassetid://${spriteAssets[i]}"`,
            ImageRectOffset: `Vector2.new(${img.x}, ${img.y})`,
            ImageRectSize: `Vector2.new(${img.width}, ${img.height})`
          };
        }
      }
      return config;
    }
    // 生成精灵图
    await generateSprite(bins, folderPath, outputFolder);
    // 收集当前文件夹的配置
    const folderConfig = await collectConfig(bins, folderPath);
    // 合并到全局配置中
    // 如果globalConfig中存在folderPath，则遍历folderConfig添加到globalConfig中
    for (const folderPath in folderConfig) {
      if (globalConfig[folderPath]) {
        for (const imageName in folderConfig[folderPath]) {
          globalConfig[folderPath][imageName] = folderConfig[folderPath][imageName];
        }
      } else {
        globalConfig[folderPath] = folderConfig[folderPath];
      }
    }
    groupIndex++;
    // 遍历所有bin，删除resized_开头的图片
    for (let i = 0; i < bins.length; i++) {
      const bin = bins[i];
      for (const img of bin.images) {
        if (!fs.existsSync(img.imagePath)) continue;
        if (path.basename(img.imagePath).startsWith('resized_')) {
          fs.unlinkSync(img.imagePath);
          console.log(`删除多余的图片: ${img.imagePath}`);
        }
      }
    }
    }
    // 删除多余的缓存精灵图信息文件
    const allCacheFiles = fs.readdirSync(cacheDir);
    
    // 遍历cache中的所有json文件，如果没有找到对应的png文件，则删除该json文件
    for (const file of allCacheFiles) {
      if (file.endsWith('_info.json')) {
        const pngFile = file.replace('_info.json', '.png');
        if (!allCacheFiles.includes(pngFile)) {
          fs.unlinkSync(path.join(cacheDir, file));
          console.log(`删除多余的精灵图信息文件: ${file}`);
        }
      }
    }

    // 获取根文件夹名称
    const rootFolderName = path.basename(inputFolder);
    
    // 检查是否使用 -j 参数生成 JSON 格式
    const generateJson = process.argv.includes('-j');
    // 检查是否使用 -t 参数生成 TypeScript 格式
    const generateTs = process.argv.includes('-t');
    
    if (generateJson) {
      // 为JSON格式转换数据，移除字符串引号和函数调用
      const jsonConfig = {};
      for (const [folderName, config] of Object.entries(globalConfig)) {
        jsonConfig[folderName] = {};
        for (const [name, data] of Object.entries(config)) {
          jsonConfig[folderName][name] = {
            Image: data.Image.replace(/"/g, ''),
            ImageRectOffset: data.ImageRectOffset.replace('Vector2.new(', '[').replace(')', ']'),
            ImageRectSize: data.ImageRectSize.replace('Vector2.new(', '[').replace(')', ']')
          };
        }
      }
      
      // 生成 JSON 配置文件
      const jsonContent = JSON.stringify(jsonConfig, null, 2);
      const configPath = path.join(outputFolder, `${rootFolderName}.json`);
      fs.writeFileSync(configPath, jsonContent, 'utf8');
      console.log(`生成JSON配置文件: ${configPath}`);
    } else if (generateTs) {
      // 生成 TypeScript 配置文件
      let tsContent = '// Roblox TypeScript 精灵图配置\n';
      tsContent += 'interface SpriteConfig {\n';
      tsContent += '\tImage: string;\n';
      tsContent += '\tImageRectOffset: Vector2;\n';
      tsContent += '\tImageRectSize: Vector2;\n';
      tsContent += '}\n\n';
      
      // 为每个文件夹生成 export const
      for (const [folderName, config] of Object.entries(globalConfig)) {
        // 将文件夹名转换为合法的变量名，但保留中文字符
        const variableName = folderName.replace(/[^a-zA-Z0-9_\u4e00-\u9fa5]/g, '_');
        
        tsContent += `export const ${variableName}: Record<string, SpriteConfig> = {\n`;
        for (const [name, data] of Object.entries(config)) {
          // 使用引号包围属性名以支持中文和特殊字符
          tsContent += `\t"${name}": {\n`;
          tsContent += `\t\tImage: ${data.Image},\n`;
          // 将 Vector2.new() 转换为 new Vector2() 以符合 TypeScript 语法
          tsContent += `\t\tImageRectOffset: ${data.ImageRectOffset.replace('Vector2.new', 'new Vector2')},\n`;
          tsContent += `\t\tImageRectSize: ${data.ImageRectSize.replace('Vector2.new', 'new Vector2')}\n`;
          tsContent += '\t},\n';
        }
        tsContent += '};\n\n';
      }
      
      // 使用根文件夹名称作为配置文件名
      const configPath = path.join(outputFolder, `${rootFolderName}.ts`);
      fs.writeFileSync(configPath, tsContent, 'utf8');
      console.log(`生成TypeScript配置文件: ${configPath}`);
    } else {
      // 生成最终的Lua配置文件
      let luaContent = 'return {';
      for (const [folderName, config] of Object.entries(globalConfig)) {
        luaContent += `\n    ["${folderName}"] = {`;
        for (const [name, data] of Object.entries(config)) {
          luaContent += `\n        ["${name}"] = {`;
          luaContent += `\n            Image = ${data.Image},`;
          luaContent += `\n            ImageRectOffset = ${data.ImageRectOffset},`;
          luaContent += `\n            ImageRectSize = ${data.ImageRectSize}`;
          luaContent += '\n        },';
        }
        luaContent += '\n    },';
      }
      luaContent += '\n}';

      // 使用根文件夹名称作为配置文件名
      const configPath = path.join(outputFolder, `${rootFolderName}.lua`);
      fs.writeFileSync(configPath, luaContent, 'utf8');
      console.log(`生成Lua配置文件: ${configPath}`);
    }

  } catch (error) {
    console.error(`处理图片时发生错误: ${error.message}`);
  }
};

processImages().catch(err => console.error(err));